import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 numel
)
{
    .reg .pred  %p_loop, %p_oob;
    .reg .b32   %r_idx, %r_stride, %r_numel, %r_tid, %r_bid, %r_bdim, %r_gdim;
    .reg .b64   %rd_in, %rd_out, %rd_off;
    .reg .f32   %f_x, %f_negx, %f_t, %f_e, %f_den, %f_res;

    // Load parameters
    ld.param.u64 %rd_in,   [input_ptr];
    ld.param.u64 %rd_out,  [output_ptr];
    ld.param.u32 %r_numel, [numel];

    // Compute global thread index and stride
    mov.u32 %r_tid,  %tid.x;
    mov.u32 %r_bid,  %ctaid.x;
    mov.u32 %r_bdim, %ntid.x;
    mov.u32 %r_gdim, %nctaid.x;

    mad.lo.s32 %r_idx, %r_bid, %r_bdim, %r_tid;   // idx = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.s32 %r_stride, %r_bdim, %r_gdim;       // stride = blockDim.x * gridDim.x

    // Early exit if starting index is out of bounds
    setp.ge.u32 %p_oob, %r_idx, %r_numel;
    @%p_oob bra DONE;

LOOP:
    // Load x
    mul.wide.u32 %rd_off, %r_idx, 4;
    add.s64 %rd_off, %rd_in, %rd_off;
    ld.global.f32 %f_x, [%rd_off];

    // y = 1 / (1 + exp(-x))
    neg.f32 %f_negx, %f_x;
    // Convert e^t to 2^(t * log2(e)) with log2(e) ~= 1.44269504f
    mul.rn.f32 %f_t, %f_negx, 1.44269504;
    ex2.approx.f32 %f_e, %f_t;
    add.f32 %f_den, %f_e, 1.0;
    rcp.rn.f32 %f_res, %f_den;

    // Store result
    mul.wide.u32 %rd_off, %r_idx, 4;
    add.s64 %rd_off, %rd_out, %rd_off;
    st.global.f32 [%rd_off], %f_res;

    // Next element
    add.u32 %r_idx, %r_idx, %r_stride;
    setp.lt.u32 %p_loop, %r_idx, %r_numel;
    @%p_loop bra LOOP;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        # Ensure PTX is ASCII-only to avoid ptxas issues
        try:
            PTX_SOURCE.encode("ascii")
        except UnicodeEncodeError as e:
            raise RuntimeError(f"Non-ASCII in PTX at position {e.start}: {repr(PTX_SOURCE[e.start:e.end])}") from e
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a custom PTX kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Allocate output tensor
        y = torch.empty_like(x)

        # Compute launch configuration
        numel = x.numel()
        block_x = 256
        # Use a bounded grid to avoid excessively large grid sizes
        grid_x = min(65535, (numel + block_x - 1) // block_x)

        module = _get_ptx_module()
        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, y, i32(numel)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

